import{z as n,x as d,o,c as A,q as s,j as B,D as e,d as t,s as r,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"DDoS 缓解","description":"","frontmatter":{"title":"DDoS 缓解","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ddos-mitigation.md","filePath":"cs/ddos-mitigation.md","lastUpdated":1791413859000}'),p={name:"cs/ddos-mitigation.md"};function D(m,a,c,h,C,f){const i=d("Mermaid");return o(),A("div",null,[a[2]||(a[2]=s('<h1 id="ddos-缓解" tabindex="-1">DDoS 缓解 <a class="header-anchor" href="#ddos-缓解" aria-label="Permalink to &quot;DDoS 缓解&quot;">​</a></h1><div class="epigraph"><p>分布式拒绝服务用流量或连接耗尽容量。缓解是清洗、任播、过载降级与上游协作，不是在应用里再加一把锁。可用性与完整在此打架：宁可降级也不能把清洗做成永久中间人而不写进模型。</p><footer>—— 据 RFC 4732；Mirkovic and Reiher 对 DDoS 的分类；对照[DoS 与放大](/cs/dos-amplify)</footer></div><p>上一课<a href="/cs/honeypot">蜜罐</a>观扫描。缺口是<strong>容量轴</strong>：主干放大课已有反射。本课收缓解：清洗中心、Anycast、挑战、弹性。不写如何发动 DDoS。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>带宽、状态表、应用线程都可被耗尽。缺口是分层：接入、ISP、CDN、应用过载保护。SYN 洪水与应用层洪水对策不同。</p><p><span class="marginnote">术语翻译：任播（Anycast）就是让同一个 IP 在全球多个地点同时对外服务、由路由协议自动把访问导向最近一个的手段——攻击流量也被摊到几十个接入点，单一机房要扛的洪峰被切成了几十份。</span></p><h3 id="放大" tabindex="-1">放大 <a class="header-anchor" href="#放大" aria-label="Permalink to &quot;放大&quot;">​</a></h3><p>开放解析器与 NTP 一类在主干已点名。缓解包括源头入站过滤（BCP 38）。</p><p><span class="marginnote">数字实例：memcached 反射一度能把请求放大约 5000 倍——攻击者发 200 Mbps 的伪造查询，受害者就要接约 1 Tbps 的回包。这正是源头入站过滤（BCP 38）关键的原因：伪造源封不住，放大器就永远有市场。</span></p><p><span class="marginnote">RFC 4732。禁止攻击指导。端口扫描下一课是侦察，不是洪水。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照容积与应用层。任播吸收、速率限制、降级静态页。指出 TLS 握手昂贵（密码学课已见）。</p>',13)),(o(),B(l,null,{default:e(()=>[r(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20FLOOD%5B%22%E8%BF%87%E9%87%8F%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20SCRUB%5B%22%E6%B8%85%E6%B4%97%E6%88%96%E4%BB%BB%E6%92%AD%22%5D%0A%20%20FLOOD%20--%3E%20DEG%5B%22%E8%BF%87%E8%BD%BD%E9%99%8D%E7%BA%A7%22%5D%0A%20%20SRC%5B%22%E6%BA%90%E8%BF%87%E6%BB%A4%20BCP38%22%5D%20--%3E%20LESS%5B%22%E5%87%8F%E5%B0%91%E4%BC%AA%E9%80%A0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"可用性是 CIA 的 A。清洗改变路径，要认证与合同，否则成中间人。扫描下一课是发现面，常是洪水的前奏。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"常见误区：初学者容易以为「代码写快一点、锁加好一点」就能抗 DDoS。攻击耗尽的是带宽、连接表这类容量资源，服务器内部再高效也省不出上游带宽——缓解必须发生在路径上（清洗、任播、上游协作），而不是单台机器里。")],-1)),(o(),B(l,null,{default:e(()=>[r(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%AE%B9%E7%A7%AF%E5%9E%8B%EF%BC%9A%E7%81%8C%E6%BB%A1%E5%B8%A6%E5%AE%BD%22%5D%20--%3E%20A1%5B%22%E5%AF%B9%E7%AD%96%EF%BC%9A%E4%BB%BB%E6%92%AD%E5%88%86%E6%95%A3%20%2B%20%E4%B8%8A%E6%B8%B8%E6%B8%85%E6%B4%97%22%5D%0A%20%20B%5B%22%E5%8D%8F%E8%AE%AE%E5%9E%8B%EF%BC%9A%E8%80%97%E5%B0%BD%E8%BF%9E%E6%8E%A5%E7%8A%B6%E6%80%81%E8%A1%A8%22%5D%20--%3E%20B1%5B%22%E5%AF%B9%E7%AD%96%EF%BC%9ASYN%20cookie%EF%BC%8C%E6%8F%90%E5%89%8D%E7%94%A9%E7%BB%99%E6%B8%85%E6%B4%97%E4%B8%AD%E5%BF%83%22%5D%0A%20%20C%5B%22%E5%BA%94%E7%94%A8%E5%9E%8B%EF%BC%9A%E8%80%97%E5%B0%BD%E7%BA%BF%E7%A8%8B%E4%B8%8E%20CPU%22%5D%20--%3E%20C1%5B%22%E5%AF%B9%E7%AD%96%EF%BC%9A%E6%8C%91%E6%88%98%E3%80%81%E9%80%9F%E7%8E%87%E9%99%90%E5%88%B6%E3%80%81%E9%99%8D%E7%BA%A7%E9%9D%99%E6%80%81%E9%A1%B5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写发动攻击。端口扫描与 Nmap 下一课：侦察方法论，防御视角。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>蜜罐不解决容量；DDoS 要清洗与降级。</li><li>容积与应用层对策不同。</li><li>源过滤减少伪造放大。</li><li>下一课端口扫描。</li><li>出处：RFC 4732；Mirkovic and Reiher；BCP 38；<a href="/cs/dos-amplify">dos-amplify</a>。</li></ul>',4))])}const u=n(p,[["render",D]]);export{S as __pageData,u as default};
